"""Topic specifications for the bank factory (scripts/bankgen.py).

One spec = one topic. A topic is a matrix of CELLS: each cell is one *decision* the learner must make,
with its own typical mistakes of Russian speakers. Everything else (formats, levels, prompts, validation,
seed assignment) is generic and lives in bankgen.py.

Editing rules
  * `share` of the cells in one topic must add up to 1.0 (checked by `bankgen.py plan`).
  * `cons` = construction tags written to the output; the validator accepts only the tags listed here.
  * `hooks` = scene features a seed should contain for this cell (the seed catalogue is written for them).
"""

GENERIC_FORMATS = {"gap": 40, "mini": 22, "mc": 15, "fix": 12, "which": 6, "transform": 5}


def cell(id, name, share, what, decision, mistakes, example, cons, hooks, formats=None, notes="", levels=None):
    return dict(id=id, name=name, share=share, what=what, decision=decision, mistakes=mistakes,
                example=example, cons=cons, hooks=hooks, formats=formats or {}, notes=notes, levels=levels)


SPECS = {}

