def check_specs():
    problems = []
    for name, s in SPECS.items():
        tot = round(sum(c["share"] for c in s["cells"]), 3)
        if abs(tot - 1) > 0.015:
            problems.append(f"{name}: shares add up to {tot}")
    return problems


if __name__ == "__main__":
    for p in check_specs():
        print("PROBLEM", p)
    for n, s in SPECS.items():
        print(n, s["target"], len(s["cells"]), "cells")
